                    var info = lib.character[name];
                    if (!info) {
                        info = lib.character[player.name1];
                        if (!info) {
                            return false;
                        }
                    }
                    if (info[1] == 'radiance_group_savior') return true;
                    if (!lib.watersky.radiance.radianceGroupSetting) return false;
                    if (!['radiance_group_free', 'radiance_group_underworld', 'radiance_group_heaven', 'radiance_group_lost'].includes(info[1])) return false;
                    return true;
