                                    var base = 7;
                                    var suits = _status.event.suits;
                                    if (att > 1 && !suits.includes(card.suit)) {
                                        base += 3;
                                    }
                                    if (att < 0 && suits.includes(card.suit)) {
                                        base -= 2;
                                    }
                                    return base - get.value(card);
