                    content() {
                        'step 0';
                        event.forceDie = true;
                        delete event.filterStop;
                        var num = player.countMark('radiance_guangqi');
                        if (player.hasSkill('radiance_guangqi_used')) {
                            player.removeMark('radiance_guangqi', 1, false);
                        } else {
                            player.addTempSkill('radiance_guangqi_used', 'roundStart');
                        }
                        var cards = get.cards(num);
                        game.cardsGotoOrdering(cards);
                        var next = player.chooseToMove();
                        next.set('list', [
                            ['牌堆顶', cards],
                            ['牌堆底', []],
                            ['获得', []],
                        ]);
                        next.set('forced', true);
                        next.set('prompt', '光启:将任意张牌置于牌堆顶和牌堆底,且可以获得其中' + get.cnNumber(Math.max(player.getDamagedHp(), 1)) + '张');
                        next.set('filterMove', function (from, to, moved) {
                            if (to == 2 && moved[2].length >= Math.max(player.getDamagedHp(), 1)) return false;
                            return true;
                            if (moved[2].length) {
                                if (to == 2) return false;
                                if (typeof to == 'number') return true;
                                if (from.link == moved[2][0] && !_status.event.player.hasUseTarget(to.link)) return false;
                                if (to.link == moved[2][0] && !_status.event.player.hasUseTarget(from.link)) return false;
                            }
                            if (to == 2 && !_status.event.player.hasUseTarget(from)) return false;
                            return true;
                        });
                        next.set('filterOk', function (moved) {
                            if (moved[2].length > Math.max(player.getDamagedHp(), 1)) return false;
                            return true;
                            if (moved[2].length == 1 && !player.hasUseTarget(moved[2][0])) return false;
                            return true;
                        });
                        next.processAI = function (list) {
                            var cards = list[0][1],
                                player = _status.event.player,
                                current = _status.event.getTrigger().player;
                            var top = [];
                            var judges = current.getCards('j');
                            var att_cur = get.sgn(get.attitude(player, current));
                            var stopped = false;
                            var num = Math.max(player.getDamagedHp(), 1);
                            if (!current.hasWuxie()) {
                                for (var i = 0; i < judges.length; i++) {
                                    var judge = get.judge(judges[i]);
                                    cards.sort(function (a, b) {
                                        return (judge(b) - judge(a)) * att_cur;
                                    });
                                    if (judge(cards[0]) * att_cur < 0) {
                                        stopped = true;
                                        break;
                                    } else {
                                        top.push(cards.shift());
                                    }
                                }
                            }
                            var touse,
                                eff = 0;
                            if (Array.isArray(cards))
                                for (var i of cards) {
                                    var card = i;
                                    if (!player.hasUseTarget(card)) continue;
                                    if (player.getUseValue(card) > eff) {
                                        eff = player.getUseValue(card);
                                        touse = card;
                                    }
                                }
                            if (touse) {
                                touse = [touse];
                            } else {
                                touse = [];
                            }
                            var togain = cards.filter((card) => get.value(card, player) > 0);
                            togain.sort(function (a, b) {
                                return get.value(b, player) - get.value(a, player);
                            });
                            if (togain.length > num) togain = togain.slice(0, num);
                            cards.removeArray(togain);
                            var bottom;
                            if (!stopped) {
                                cards.sort(function (a, b) {
                                    return (get.value(b, current) - get.value(a, current)) * att_cur;
                                });
                                while (cards.length) {
                                    if (att_cur > 0 && get.value(cards[0], current) <= 5) break;
                                    top.push(cards.shift());
                                }
                            }
                            bottom = cards;
                            return [top, bottom, togain];
                        };
                        ('step 1');
                        event.top = result.moved[0];
                        event.bottom = result.moved[1];
                        if (result.moved[2].length) {
                            player.gain(result.moved[2], 'draw');
                        }
                        ('step 2');
                        var top = event.top;
                        var bottom = event.bottom;
                        top.reverse();
                        for (var i of top) {
                            ui.cardPile.insertBefore(i, ui.cardPile.firstChild);
                        } //QQQ
                        for (var i = 0; i < bottom.length; i++) {
                            ui.cardPile.appendChild(bottom[i]);
                        }
                        player.popup(get.cnNumber(top.length) + '上' + get.cnNumber(bottom.length) + '下');
                        game.log(player, '将' + get.cnNumber(top.length) + '张牌置于牌堆顶');
                        game.updateRoundNumber();
                    },
                    global: 'radiance_guangqi_clear',
