                                if (player.storage.radiance_wuta_suit.length > 3 || player.storage.radiance_wuta_choice.length > 3) {
                                    player.storage.radiance_wuta_suit.length = 0;
                                    player.storage.radiance_wuta_choice.length = 0;
                                    game.log(player, '重置了', 'radiance_wuta');
                                }
